UPDATE fields f SET enum_values = '[{"value":"ja","label_de":"werkseitig vorkonfektio- nierten Bahnen für gering beanspruchte Nutzungen (z. B. Gartenteiche) sind Bahnendicken ≥ 1,0 mm zulässig. Abdichtungen mit Kunststoff- und Elastomerbahnen sind i. d. R. einlagig.","order_index":1},{"value":"nein","label_de":"nein — Regelfall (Mindestdicke 1,2 mm)","order_index":2}]'::jsonb
